p--custom--spacing--gap);}:root :where(.wp-block-pullquote p){margin: 0;}\";s:32:\"c48738dcb285a3f6ab83acff204fc486\";s:109:\":root :where(.wp-block-pullquote cite){font-size: var(--wp--preset--font-size--x-small);font-style: inherit;}\";s:32:\"4c7f8d21d487b654b2a290da2786be9c\";s:665:\":root :where(.wp-block-buttons-is-layout-flow) > :first-child{margin-block-start: 0;}:root :where(.wp-block-buttons-is-layout-flow) > :last-child{margin-block-end: 0;}:root :where(.wp-block-buttons-is-layout-flow) > *{margin-block-start: 10px;margin-block-end: 0;}:root :where(.wp-block-buttons-is-layout-constrained) > :first-child{margin-block-start: 0;}:root :where(.wp-block-buttons-is-layout-constrained) > :last-child{margin-block-end: 0;}:root :where(.wp-block-buttons-is-layout-constrained) > *{margin-block-start: 10px;margin-block-end: 0;}:root :where(.wp-block-buttons-is-layout-flex){gap: 10px;}:root :where(.wp-block-buttons-is-layout-grid){gap: 10px;}\";s:32:\"f9a663d22cfd53f6b24d3b357ad87fb6\";s:473:\":root :where(.wp-block-code){background-color: var(--wp--preset--color--contrast);color: var(--wp--preset--color--base);font-size: var(--wp--preset--font-size--small);padding-top: var(--wp--custom--spacing--gap);padding-right: var(--wp--custom--spacing--gap);padding-bottom: var(--wp--custom--spacing--gap);padding-left: var(--wp--custom--spacing--gap);}:root :where(.wp-block-code code){overflow-wrap: normal; overflow-x: scroll; tab-size: 4; white-space: pre !important;}\";s:32:\"2726ca459b923c2c44c4c6d01d11382f\";s:144:\":root :where(.wp-block-comment-author-name){font-size: var(--wp--preset--font-size--small);line-height: var(--wp--custom--line-height--medium);}\";s:32:\"87c687c03903638e9dacfd8222418e64\";s:137:\":root :where(.wp-block-comment-date){font-size: var(--wp--preset--font-size--small);line-height: var(--wp--custom--line-height--medium);}\";s:32:\"4aba136a6ef994b580e75270e520f2ea\";s:142:\":root :where(.wp-block-comment-edit-link){font-size: var(--wp--preset--font-size-