trast);color: var(--wp--preset--color--base);padding-top: 25px;padding-right: 30px;padding-bottom: 25px;padding-left: 30px;}:root :where(.wp-block-preformatted){overflow-wrap: normal; overflow-x: scroll; tab-size: 4; white-space: pre !important;}\";s:32:\"05d92ffd6ac07a19b8dd1567513b8a19\";s:347:\":root :where(.wp-block-quote){border-color: var(--wp--preset--color--contrast);border-width: 1px;border-style: solid;padding-top: var(--wp--custom--spacing--gap);padding-right: var(--wp--custom--spacing--gap);padding-bottom: var(--wp--custom--spacing--gap);padding-left: var(--wp--custom--spacing--gap);}:root :where(.wp-block-quote p){margin: 0;}\";s:32:\"1de7a22e22013106efc5be82788cb6c0\";s:105:\":root :where(.wp-block-quote cite){font-size: var(--wp--preset--font-size--x-small);font-style: inherit;}\";s:32:\"b3b0c401e71713486c119fb25db9c933\";s:210:\":root :where(.wp-block-separator){border-radius: 0;border-color: currentColor;border-width: 1px 0 0;border-style: solid;}:root :where(.wp-block-separator:not(.is-style-wide):not(.is-style-dots) ){width: 100px;}\";s:32:\"90eecb95bae999b175a93ef72195ee2a\";s:177:\":root :where(.wp-block-site-title){font-family: var(--wp--preset--font-family--headline);font-size: var(--wp--preset--font-size--large);font-weight: 600;letter-spacing: 0.03em;}\";s:32:\"f513d889cf971b13995cc3fffed2f39b\";s:92:\":root :where(.wp-block-site-title a:where(:not(.wp-element-button))){text-decoration: none;}\";s:32:\"700797d352047fb1c0e246d1ff942471\";s:844:\":root :where(.wp-block-social-links-is-layout-flow) > :first-child{margin-block-start: 0;}:root :where(.wp-block-social-links-is-layout-flow) > :last-child{margin-block-end: 0;}:root :where(.wp-block-social-links-is-layout-flow) > *{margin-block-start: 10px;margin-block-end: 0;}:root :where(.wp-block-social-links-is-layout-constrained) > :first-child{margin-block-start: 0;}:root :where(.wp-block-social-links-is-layout-constrained) > :last-child{margin-block-end: 0;}:root :where(.wp-block-social-links-is-layout-constrained) > *{margin-block-start: 10px;margin-block-end: 0;}:root :where(.wp-block-social-links-is-layout-flex){gap: 10px;}:root :where(.wp-block-social-links-is-layout-grid){gap: 10px;}:root :where(.wp-block-social-links.is-style-outline .wp-block-social-link ){background-color: transparent;border: 1px solid currentColor;}\";s:32:\"0f345f5e5762624e6dd52d385dbbf3d2\";s:46:\":root :where(.wp-block-spacer){margin-top: 0;}\";s:32:\"7147f9d76660c48268daa0dad9af4b9b\";s:290:\":root :where(.wp-block-table > table){font-size: var(--wp--preset--font-size--small);}:root :where(.wp-block-table > tableth ){border-color: var(--wp--preset--color--contrast) !important;}:root :where(.wp-block-table > table td){border-color: var(--wp--preset--color--contrast) !important;}\";s:32:\"298c920546a7168ce2715a02ba9da4c1\";s:53:\":root :where(.wp-block-template-part){margin-top: 0;}\";s:32:\"1b8b5af9cb7796418be3edaf7703509e\";s:145:\":root :where(.wp-block-heading){font-family: var(--wp--preset--font-family--headline);font-weight: 600;letter-spacing: 0.02em;line-height: 1.15;}\";}}', 'on'),
