(178, 'acf_site_health', '{\"version\":\"6.9.5\",\"plugin_type\":\"Secure Custom Fields\",\"update_source\":\"wordpress.org\",\"wp_version\":\"7.1\",\"mysql_version\":\"5.7.23-23\",\"is_multisite\":false,\"active_theme\":{\"name\":\"World Graph Studio\",\"version\":\"1.3.0\",\"theme_uri\":\"\",\"stylesheet\":false},\"parent_theme\":{\"name\":\"Frost\",\"version\":\"1.1\",\"theme_uri\":\"https:\\/\\/frostwp.com\\/\",\"stylesheet\":false},\"active_plugins\":{\"secure-custom-fields\\/secure-custom-fields.php\":{\"name\":\"Secure Custom Fields\",\"version\":\"6.9.5\",\"plugin_uri\":\"https:\\/\\/developer.wordpress.org\\/secure-custom-fields\\/\"},\"w3-total-cache\\/w3-total-cache.php\":{\"name\":\"W3 Total Cache\",\"version\":\"2.10.5\",\"plugin_uri\":\"https:\\/\\/www.boldgrid.com\\/totalcache\\/\"},\"worldgraph\\/worldgraph.php\":{\"name\":\"World Graph Studio - Story Core\",\"version\":\"1.0.0\",\"plugin_uri\":\"https:\\/\\/github.com\\/videohead\\/storyos\"}},\"ui_field_groups\":\"15\",\"php_field_groups\":\"0\",\"json_field_groups\":\"0\",\"rest_field_groups\":\"14\",\"all_location_rules\":[\"post_type==worldgraph_asset\",\"post_type==worldgraph_character\",\"post_type==worldgraph_conn\",\"post_type==worldgraph_editorial\",\"post_type==worldgraph_episode\",\"post_type==worldgraph_location\",\"post_type==worldgraph_org\",\"post_type==worldgraph_project\",\"post_type==worldgraph_prop\",\"post_type==worldgraph_scene\",\"post_type==worldgraph_shot\",\"post_type==worldgraph_sound\",\"post_type==worldgraph_world\",\"post_type==worldgraph_board\",\"post_type==worldgraph_template\"],\"field_groups_with_single_block_rule\":\"0\",\"field_groups_with_multiple_block_rules\":\"0\",\"field_groups_with_blocks_and_other_rules\":\"0\",\"number_of_fields_by_type\":{\"text\":49,\"taxonomy\":8,\"wysiwyg\":29,\"number\":11,\"select\":20,\"post_object\":28,\"textarea\":24,\"date_picker\":3,\"user\":1,\"relationship\":2,\"repeater\":1},\"number_of_third_party_fields_by_type\":[],\"post_